pub fn pro_sell_verify_account_keys(
    accounts: ProSellAccounts<'_, '_>,
    keys: ProSellKeys,
) -> Result<(), (Pubkey, Pubkey)> {
    for (actual, expected) in [
        (*accounts.token_a_program.key, keys.token_a_program),
        (*accounts.token_b_program.key, keys.token_b_program),
        (*accounts.associated_token_program.key, keys.associated_token_program),
        (*accounts.system_program.key, keys.system_program),
        (*accounts.liquidity_pool_state.key, keys.liquidity_pool_state),
        (*accounts.user.key, keys.user),
        (*accounts.token_a_mint.key, keys.token_a_mint),
        (*accounts.token_b_mint.key, keys.token_b_mint),
        (*accounts.user_token_a_vault.key, keys.user_token_a_vault),
        (*accounts.user_token_b_vault.key, keys.user_token_b_vault),
        (*accounts.token_a_vault.key, keys.token_a_vault),
        (*accounts.token_b_vault.key, keys.token_b_vault),
        (*accounts.protocol_config.key, keys.protocol_config),
        (
            *accounts.instruction_sysvar_account_info.key,
            keys.instruction_sysvar_account_info,
        ),
    ] {
        if actual != expected {
            return Err((actual, expected));
        }
    }
    Ok(())
}
pub fn pro_sell_verify_writable_privileges<'me, 'info>(
    accounts: ProSellAccounts<'me, 'info>,
) -> Result<(), (&'me AccountInfo<'info>, ProgramError)> {
    for should_be_writable in [
        accounts.liquidity_pool_state,
        accounts.user_token_a_vault,
        accounts.user_token_b_vault,
        accounts.token_a_vault,
        accounts.token_b_vault,
        accounts.protocol_config,
    ] {
        if !should_be_writable.is_writable {
            return Err((should_be_writable, ProgramError::InvalidAccountData));
        }
    }
    Ok(())
}
pub fn pro_sell_verify_signer_privileges<'me, 'info>(
    accounts: ProSellAccounts<'me, 'info>,
) -> Result<(), (&'me AccountInfo<'info>, ProgramError)> {
    for should_be_signer in [accounts.user] {
        if !should_be_signer.is_signer {
            return Err((should_be_signer, ProgramError::MissingRequiredSignature));
        }
    }
    Ok(())
}
pub fn pro_sell_verify_account_privileges<'me, 'info>(
    accounts: ProSellAccounts<'me, 'info>,
) -> Result<(), (&'me AccountInfo<'info>, ProgramError)> {
    pro_sell_verify_writable_privileges(accounts)?;
    pro_sell_verify_signer_privileges(accounts)?;
    Ok(())
}
